export function fizzbuzz(n) {
  let result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 3 === 0 && i % 5 === 0) {
      result.push('FizzBuzz');
    } else if (i % 3 === 0) {
      result.push('Fizz');
    } else if (i % 5 === 0) {
      result.push('Buzz');
    } else {
      result.push(i.toString());
    }
  }
  return result.join(' ');
}

class Median:
    def median(self, numbers):
        numbers.sort()
        n = len(numbers)
        mid = n // 2
        if n % 2 == 0:
            return (numbers[mid - 1] + numbers[mid]) / 2
        else:
            return numbers[mid]
